    std::uint8_t* const bytes_ = table_.data();

    ::tafla::store_le(bytes_, std::uint32_t{44});
    ::tafla::store_le(bytes_ + 4, std::uint32_t{45});
    ::tafla::store_le(bytes_ + 8, std::uint32_t{46});
    ::tafla::store_le(bytes_ + 12, std::uint32_t{48});
